window.QUESTION_BANK_CHUNKS["tech_判断"]={"id":"tech_判断","name":"建设工程安全生产技术—判断","questionCount":590,"type":"judge","questions":[{"id":1,"type":"judge","stem":"盾构施工的管片贮存场地应坚实平整。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_1"},{"id":2,"type":"judge","stem":"盾构机安装完毕后，经项目经理验收签字后即可投入使用。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_2"},{"id":3,"type":"judge","stem":"机械在使用过程中可以视情况超速作业。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_3"},{"id":4,"type":"judge","stem":"机械上的各种安全防护和保险装置及各种安全信息装置必须齐全有效。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_4"},{"id":5,"type":"judge","stem":"大型内燃机械周边可以堆放适量的易燃物品。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_5"},{"id":6,"type":"judge","stem":"操作人员在操作过程中，应集中精力，正确操作，并应检查机械工况，不得擅自离开工作岗位。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_6"},{"id":7,"type":"judge","stem":"机械带病运转时，应派专人进行监督管理。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_7"},{"id":8,"type":"judge","stem":"内燃机启动前，离合器应处于分离状态；有减压装置的柴油机，应先打开减压阀(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_8"},{"id":9,"type":"judge","stem":"内燃机工作时，水温超过90℃时，必须立即停机，不得怠速运转。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_9"},{"id":10,"type":"judge","stem":"排气管向上的内燃机，停机后应在排气管口上加盖(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_10"},{"id":11,"type":"judge","stem":"有减压装置的内燃机，宜使用减压杆进行熄火停机。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_11"},{"id":12,"type":"judge","stem":"不得对旋转着的发电机进行维修、清理。运转中的发电机不得使用帆布等物体遮盖(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_12"},{"id":13,"type":"judge","stem":"发电机组电源与外电线路电源连锁后，可以与外电并联运行。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_13"},{"id":14,"type":"judge","stem":"空气压缩机停机后，在离岗前应关闭冷却水阀门，打开放气阀，放出各级冷却器和贮气罐内的油水和存气(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_14"},{"id":15,"type":"judge","stem":"机械运行中，不得接触转动部位。在修理工作装置时，应将工作装置降到最低位置，或者适当悬空。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_15"},{"id":16,"type":"judge","stem":"土石方机械施工时，遇到施工标志及防护设施被破坏时应立即停工(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_16"},{"id":17,"type":"judge","stem":"机械回转作业时，配合人员必须在机械回转半径以外工作。当需要在处于回转状态的机械回转半径以内工作时，必须有专人监管。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_17"},{"id":18,"type":"judge","stem":"行驶或作业中的机械，除驾驶室外的任何地方不得有乘员。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_18"},{"id":19,"type":"judge","stem":"单斗挖掘机启动前，应将主离合器分离，各操纵杆放在空档位置，确认安全后，可直接启动设备。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_19"},{"id":20,"type":"judge","stem":"单斗挖掘机作业时，应保持水平位置，行走机构应制动。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_20"},{"id":21,"type":"judge","stem":"单斗挖掘机作业时，轮胎可不揳紧。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_21"},{"id":22,"type":"judge","stem":"单斗挖掘机在坑边作业时，当发现有塌方危险时，应立即处理险情，或将挖掘机撤至安全地带。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_22"},{"id":23,"type":"judge","stem":"单斗挖掘机作业时，斗臂在抬高及回转时，不得碰到坑、沟侧壁或其他物体。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_23"},{"id":24,"type":"judge","stem":"单斗挖掘机作业时，当液压缸将伸缩到极限位置时，应动作平稳，不得冲撞极限块。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_24"},{"id":25,"type":"judge","stem":"履带式挖掘机可以在坡道上变速。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_25"},{"id":26,"type":"judge","stem":"挖掘机在坡道上行走时熄火，应立即制动，并应揳住履带或轮胎，重新发动后，再继续行走。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_26"},{"id":27,"type":"judge","stem":"挖掘装载机作业时，回转应平稳，且不得用装载斗砸实沟槽的侧面。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_27"},{"id":28,"type":"judge","stem":"挖掘装载机装载作业前，应将挖掘装置的回转机构置于中间位置，并应采用拉板固定。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_28"},{"id":29,"type":"judge","stem":"铲斗提升臂在举升时，可以使用阀的浮动位置。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_29"},{"id":30,"type":"judge","stem":"挖掘装载机停放时间超过1d时，应使后轮离地，并应在后悬架下面用垫块支撑。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_30"},{"id":31,"type":"judge","stem":"推土机在坡道牵引其他机构设备时，钢丝绳的连接应牢固可靠。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_31"},{"id":32,"type":"judge","stem":"推土机启动前，应将主离合器分离，各操纵杆放在空挡位置。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_32"},{"id":33,"type":"judge","stem":"推土机启动后应检查各仪表指示值、液压系统，在确认运转正常，方可全载荷作业。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_33"},{"id":34,"type":"judge","stem":"下坡时，当推土机下行速度大于内燃机传动速度时，转向操纵的方向应与平地行走时操纵的方向相反，并不得使用制动器。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_34"},{"id":35,"type":"judge","stem":"拖式铲运机开动前，应使铲斗紧贴地面，机械周围不得有障碍物。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_35"},{"id":36,"type":"judge","stem":"拖式铲运机作业中，严禁人员上下机械，传递物件，以及在铲斗内、 拖把或机架上坐立。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_36"},{"id":37,"type":"judge","stem":"光轮压路机需要增加机重时，当气温降至-5℃，可在滚轮内加砂或水。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_37"},{"id":38,"type":"judge","stem":"采用静作用压路机在新建场地上进行碾压时，应从中间向两侧碾压。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_38"},{"id":39,"type":"judge","stem":"采用静作用压路机在新建场地上进行碾压时，压路机距场地边缘不应少于0.2m。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_39"},{"id":40,"type":"judge","stem":"采用静作用压路机在坑边碾压施工时，应由里侧向外侧碾压。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_40"},{"id":41,"type":"judge","stem":"采用静作用压路机在坑边碾压施工时，压路机距坑边不应少于0.5m。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_41"},{"id":42,"type":"judge","stem":"起伏较大的地面宜先用推土机推平，再用平地机平整。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_42"},{"id":43,"type":"judge","stem":"开动平地机时，在确认机械周围无行人及障碍物后，便可采用低速挡起步。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_43"},{"id":44,"type":"judge","stem":"作业后，平地机应停放在平坦、安全的场地，刮刀应落在地面上，手制动器应拉紧。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_44"},{"id":45,"type":"judge","stem":"装载机低速铲装时，采用前轮驱动；高速行驶时,应采用四轮驱动。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_45"},{"id":46,"type":"judge","stem":"装载机操纵手柄换向应平稳。装载机满载时，铲臂应缓慢下降。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_46"},{"id":47,"type":"judge","stem":"夯实机作业时，非夯实机操作人员距夯实机0.8m。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_47"},{"id":48,"type":"judge","stem":"采用振动冲击夯正常作业时，不得使劲下压手把：夯实松软土或上坡时，可将手把稍向下压。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_48"},{"id":49,"type":"judge","stem":"采用振动冲击夯作业时，应紧握手把，不得倾斜。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_49"},{"id":50,"type":"judge","stem":"采用强夯机械作业，从坑中提锤时，严禁挂钩人员站在锤上随锤提升。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_50"},{"id":51,"type":"judge","stem":"采用强夯机械作业时，夯锤下落后，在吊钩尚未降至夯锤吊环附近前，严禁除操作人员外的其他人员下坑挂钩。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_51"},{"id":52,"type":"judge","stem":"运输机械不得人货混装，运输过程中，料斗内不得载人。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_52"},{"id":53,"type":"judge","stem":"当运输机械水温达到70℃时，可跳级增减挡位。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_53"},{"id":54,"type":"judge","stem":"运输超限物件时，应事先勘察路线，制定运输方案，装卸人员及电工携带工具随行。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_54"},{"id":55,"type":"judge","stem":"车辆下坡时应提前换入低速挡，上坡时可在中途换入低速挡。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_55"},{"id":56,"type":"judge","stem":"车辆涉水过河时，应先探明水深、流速和水底情况，水深不得超过排气管或曲轴皮带盘，低速直线行驶，不得在中途停车或换挡。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_56"},{"id":57,"type":"judge","stem":"爆破器材的运输，应在白天进行，禁止夜间运输起爆器材和炸药。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_57"},{"id":58,"type":"judge","stem":"起爆器材与炸药、不同种类的炸药严禁同车运输(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_58"},{"id":59,"type":"judge","stem":"通过危险地区时，应先停车检查，确认可以通过后，应由交警指挥前进。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_59"},{"id":60,"type":"judge","stem":"装运氧气瓶的车厢不得有油污，氧气瓶严禁与油料或乙炔气瓶混装。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_60"},{"id":61,"type":"judge","stem":"运输爆破器材时，在人口稠密处、交叉路口和桥上（下）的停留时间不得超过15min。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_61"},{"id":62,"type":"judge","stem":"在车底进行保养、检修时，应将内燃机熄火，拉紧手制动器并将车轮揳牢。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_62"},{"id":63,"type":"judge","stem":"机动翻斗车可以在卸料工况下行驶。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_63"},{"id":64,"type":"judge","stem":"机动翻斗车行驶时，不宜紧急刹车(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_64"},{"id":65,"type":"judge","stem":"施打斜桩时，应先将桩锤提升到最高点，并将桩吊起，套入桩帽，桩尖插入桩位后再后仰立柱。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_65"},{"id":66,"type":"judge","stem":"桩机不得侧面吊桩或远距离拖桩。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_66"},{"id":67,"type":"judge","stem":"正在吊装的桩机，回转速度不得过快。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_67"},{"id":68,"type":"judge","stem":"桩孔成型后，当暂不浇注混凝土时，孔口必须及时封盖。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_68"},{"id":69,"type":"judge","stem":"桩机作业中，当停机时间较长时，应将桩锤落下垫稳。检修时，桩锤应适当悬空。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_69"},{"id":70,"type":"judge","stem":"柴油锤打桩过程中，应有专人负责拉好曲臂上的控制绳，在意外情况下，可使用控制绳紧急停锤。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_70"},{"id":71,"type":"judge","stem":"柴油锤运转时，冲击部分的跳起高度应符合使用说明书的要求，达到规定高度时，应加大油门。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_71"},{"id":72,"type":"judge","stem":"柴油锤启动前，柴油锤、桩帽和桩应在同一轴线上，不得偏心打桩。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_72"},{"id":73,"type":"judge","stem":"转盘钻孔机的钻头和钻杆连接螺纹应良好，出现滑扣时，应降低标准使用。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_73"},{"id":74,"type":"judge","stem":"转盘钻孔机作业过程中钻进受阻，应采用缓冲击法解除；查明原因后，采取措施继续钻进。。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_74"},{"id":75,"type":"judge","stem":"螺旋钻孔机运转时，应有专人看护，防止电缆线被缠入钻杆。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_75"},{"id":76,"type":"judge","stem":"螺旋钻孔机钻孔时，应及时用手清除螺旋片中的泥土。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_76"},{"id":77,"type":"judge","stem":"螺旋钻孔机作业完毕，应将钻杆及钻头全部提升至孔外，待清除钻杆和螺旋叶片上的泥土后，再将钻头放下接触地面。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_77"},{"id":78,"type":"judge","stem":"深层搅拌机就位后，应检查搅拌机的垂直度和导向架的水平度。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_78"},{"id":79,"type":"judge","stem":"深层搅拌机发生卡钻、停钻或管路堵塞现象时，应立即停机，并应将搅拌头提离地面，查明原因后妥善处理。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_79"},{"id":80,"type":"judge","stem":"成槽机安装时，抓斗应放置在把杆铅锤线下方的地面上,把杆角度宜为75°~90°。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_80"},{"id":81,"type":"judge","stem":"成槽机运输时，电缆及油管应卷绕整齐，并应垫高油管盘和电缆盘。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_81"},{"id":82,"type":"judge","stem":"当需进入混凝土搅拌机搅拌筒内作业时，应先切断电源，锁好开关箱，悬挂“注意安全”的警示牌，并派专人监护。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_82"},{"id":83,"type":"judge","stem":"在混凝土搅拌机料斗下方清理或检修时，应将料斗提升至上止点，并用保险销锁牢或用保险链挂牢。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_83"},{"id":84,"type":"judge","stem":"混凝土搅拌运输车装料前应先启动内燃机空载运转，并低速旋转搅拌筒0〜2min。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_84"},{"id":85,"type":"judge","stem":"出料作业时，应将混凝土搅拌运输车停靠在地势平坦处，与基坑及输电线路保持安全距离，并应锁定制动系统。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_85"},{"id":86,"type":"judge","stem":"进入混凝土搅拌运输车搅拌筒维修、清理混凝土前，应将发动机熄火，操作杆置于“搅动”位置并锁定，取出发动机钥匙。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_86"},{"id":87,"type":"judge","stem":"混凝土输送泵泵送前应向料斗加入清水和水泥砂浆润滑泵及管道。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_87"},{"id":88,"type":"judge","stem":"当敷设向下倾斜的混凝土输送泵管道时，应在泵与斜管之间敷设长度不小于3倍落差的水平管。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_88"},{"id":89,"type":"judge","stem":"混凝土泵在开始或停止泵送混凝土前，作业人员应与出料软管保持安全距离，作业人员不得在出料口下方逗留(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_89"},{"id":90,"type":"judge","stem":"混凝土泵作业时，应及时进行维修。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_90"},{"id":91,"type":"judge","stem":"混凝土泵车作业前，应将支腿打开，并应采用垫木垫平, 车身的倾斜度不应大于3°。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_91"},{"id":92,"type":"judge","stem":"当布料杆处于全伸状态时，混凝土泵车的移动速度不得超过 10km/h。。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_92"},{"id":93,"type":"judge","stem":"混凝土泵车的布料配管和布料软管不得接长。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_93"},{"id":94,"type":"judge","stem":"插入式振捣器的电缆线接头不得拖地。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_94"},{"id":95,"type":"judge","stem":"平板式振捣器应采用耐气候型橡皮护套铜芯软电缆，并不得有接头和承受任何外力。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_95"},{"id":96,"type":"judge","stem":"平板式振捣器作业时应使用牵引绳或牵拉电缆来控制移动速度。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_96"},{"id":97,"type":"judge","stem":"在同一块混凝土模板上同时使用多台附着式振捣器时，各振动器的振频应一致，安装位置宜交错设置。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_97"},{"id":98,"type":"judge","stem":"混凝土喷射机作业，拖拉输送软管时不得折弯。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_98"},{"id":99,"type":"judge","stem":"手持式钢筋加工机械作业时，应佩戴绝缘手套等防护用品。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_99"},{"id":100,"type":"judge","stem":"加工较长的钢筋时，应有专人帮扶。帮扶人员应听从安全管理人员指挥，不得任意推拉。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_100"},{"id":101,"type":"judge","stem":"钢筋调直切断机的调直块未固定或防护罩未盖好前，不得送料。作业中，不得打开防护罩。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_101"},{"id":102,"type":"judge","stem":"振动压路机在碾压时，振动频率应经常改变，以达到最好的碾压效果。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_102"},{"id":103,"type":"judge","stem":"筒式柴油锤依靠活塞上下跳动来锤击桩。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_103"},{"id":104,"type":"judge","stem":"输电线路电压在1-20kV，桩架与输电线路间的安全距离应为1．5m以上。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_104"},{"id":105,"type":"judge","stem":"静力压桩力施工时无振动，无噪声，无废气污染，对地基及周围建筑物影响较小。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_105"},{"id":106,"type":"judge","stem":"混凝土泵送作业中，料斗中的混凝土平面应保持在搅拌轴线以下，供料跟不上时不要停止泵送。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_106"},{"id":107,"type":"judge","stem":"钢筋切断机滑块与导轨纵向游动间隙应小于0.5mm，横向间隙应小于0.2mm(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_107"},{"id":108,"type":"judge","stem":"搅拌车运输混凝土途中，发现水分蒸发，可适当加水，以保证混凝土质量。    (   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_108"},{"id":109,"type":"judge","stem":"钢筋切断机作业时，操作人应使用切刀的中、下部位切料，紧握钢筋对准刃口迅速投入。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_109"},{"id":110,"type":"judge","stem":"钢筋切断机作业时，操作人应用双手分在刀片两边握住钢筋切料。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_110"},{"id":111,"type":"judge","stem":"手动液压式切断机使用前，应将放油阀按顺时针方向旋紧，作业完毕后，应立即按逆时针方向旋松。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_111"},{"id":112,"type":"judge","stem":"钢筋切断机作业时，不得用手直接清除切刀附近的断头和杂物。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_112"},{"id":113,"type":"judge","stem":"钢筋弯曲机作业时，应将需弯曲的一端钢筋插入在转盘固定销的间隙内，将另一端紧靠机身固定销，并用手压紧。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_113"},{"id":114,"type":"judge","stem":"不得用钢筋弯曲机弯曲未经冷拉或带有锈皮的钢筋。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_114"},{"id":115,"type":"judge","stem":"钢筋冷拉时，操作人员应能见到全部冷拉场地。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_115"},{"id":116,"type":"judge","stem":"钢筋冷拉时，卷扬钢丝绳应经开口式导向滑轮，并应和被拉钢筋成直角。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_116"},{"id":117,"type":"judge","stem":"钢筋冷拔机作业时，冷拔模架中应随时加足润滑剂，润滑剂可采用石灰和肥皂水调和晒干后的粉末。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_117"},{"id":118,"type":"judge","stem":"冷拔钢筋时，当钢筋的末端通过冷拔模后，应立即脱开离合器，同时用手挡住钢筋末端。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_118"},{"id":119,"type":"judge","stem":"带弯钩的钢筋不得在钢筋除锈机上进行除锈。弯度较大的钢筋宜在调直后除锈。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_119"},{"id":120,"type":"judge","stem":"采用钢筋螺纹成型机作业时，钢筋应先调直再下料。钢筋切口端面应与轴线垂直，宜采用气割下料。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_120"},{"id":121,"type":"judge","stem":"使用钢筋除锈机除锈时，应将钢筋放平，并侧身送料。除锈机正面不得站人。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_121"},{"id":122,"type":"judge","stem":"钢筋螺纹成型机在运转过程中，应及时清扫刀片上的积屑杂物。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_122"},{"id":123,"type":"judge","stem":"木工机械应使用单向开关，不得使用倒顺双向开关。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_123"},{"id":124,"type":"judge","stem":"木工机械操作人员应穿紧口衣裤，束紧长发，并戴好手套。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_124"},{"id":125,"type":"judge","stem":"木工机械工作场所，不得吸烟和动火，不得混放其他易燃易爆物品。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_125"},{"id":126,"type":"judge","stem":"带锯机作业时，当锯条裂纹长度在5mm以下时，应在裂纹终端冲一止裂孔。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_126"},{"id":127,"type":"judge","stem":"作业中，操作人员应站在带锯机的两侧，跑车开动后，行程范围内的轨道周围不应站人，不应在运行中跑车。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_127"},{"id":128,"type":"judge","stem":"带锯机运转中，当木屑堵塞吸尘管口时，应及时清理管口。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_128"},{"id":129,"type":"judge","stem":"圆盘锯的安全防护装置包括分料器、锯盘护罩、防护挡板和传动部位防护罩。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_129"},{"id":130,"type":"judge","stem":"木工电平刨刨料时，手应按在木料上，手指必须离开刨口50mm以上，严禁用手在木料后端送料跨越刨口进行刨削。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_130"},{"id":131,"type":"judge","stem":"平面刨刨料时，应保持身体平稳，用双手操作。刨小面时，手指不得高于料高一半。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_131"},{"id":132,"type":"judge","stem":"压刨床作业时，操作者应站在进料的一侧。送料时应先进大头。接料人员应在被刨料离开料辊后接料。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_132"},{"id":133,"type":"judge","stem":"压刨床作业时，刨刀与刨床台面的水平间隙应在10mm〜30mm之间。宜使用带开口槽的刨刀。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_133"},{"id":134,"type":"judge","stem":"压刨床作业时，刨料的长度不得小于前后压辊之间的距离。厚度小于10mm的薄板应垫托板作业。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_134"},{"id":135,"type":"judge","stem":"压刨床作业时，每次进刀量宜为5mm〜10mm。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_135"},{"id":136,"type":"judge","stem":"木工车床车削前，工件应卡紧，并用顶针顶紧。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_136"},{"id":137,"type":"judge","stem":"木工车床车削时，宜用手摸的方法检查工件的光滑程度。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_137"},{"id":138,"type":"judge","stem":"木工车床转动时，不得用手来制动。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_138"},{"id":139,"type":"judge","stem":"木工铣床作业前，应对铣床各部件及铣刀安装进行检查，铣刀不得有裂纹或缺损，防护装置及定位止动装置应齐全可靠。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_139"},{"id":140,"type":"judge","stem":"木工铣床作业，当木料铣切到端头时，应在已铣切的一端接料。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_140"},{"id":141,"type":"judge","stem":"卧式铣床的操作人员作业时，应站在刀刃的正面。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_141"},{"id":142,"type":"judge","stem":"开榫机加工短料时，应用垫板将木料夹牢，不得用手直接握料作业。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_142"},{"id":143,"type":"judge","stem":"盘式磨光机作业时，工件应放在向上旋转的半面进行磨光。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_143"},{"id":144,"type":"judge","stem":"锉锯机作业前，应检查并确认砂轮不得有裂缝和破损，并应安装牢固。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_144"},{"id":145,"type":"judge","stem":"顶管机作业时，顶铁与管口之间严禁采用缓冲材料衬垫。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_145"},{"id":146,"type":"judge","stem":"顶管机作业，安装后的顶铁轴线应与管道轴线平行、对称。顶铁、导轨和顶铁之间的接触面不得有杂物。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_146"},{"id":147,"type":"judge","stem":"盾构机管片吊起或升降架旋回到上方时，放置时间不应超5min。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_147"},{"id":148,"type":"judge","stem":"盾构始发、接收前，应落实盾构基座稳定措施，确保牢固。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_148"},{"id":149,"type":"judge","stem":"盾构机安装完毕后，经安全员验收签字后即可投入使用。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_149"},{"id":150,"type":"judge","stem":"盾构进出洞都存在相当大的危险性，因此，对策和监控措施必须落实到位。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_150"},{"id":151,"type":"judge","stem":"盾构机拆除退场时，机械结构部分应先按电气、泥水、注浆、液压系统顺序拆卸，最后拆卸机械结构件。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_151"},{"id":152,"type":"judge","stem":"行车垂直运输主要包括运用行车盾构推进所需的施工材料吊运至井下，将井下的出土箱等重物吊至地面。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_152"},{"id":153,"type":"judge","stem":"盾构切口与到达接收井距离小于5m时，应控制盾构推进速度、开挖面压力、排土量。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_153"},{"id":154,"type":"judge","stem":"盾构机组装前，应对推进千斤顶、拼装机、调节千斤顶进行试验验收。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_154"},{"id":155,"type":"judge","stem":"室外使用的电焊机应设有防水、防晒、防砸的机棚，不必备有消防用品。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_155"},{"id":156,"type":"judge","stem":"电焊机的外壳必须有可靠的接零或接地保护。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_156"},{"id":157,"type":"judge","stem":"焊接铜、铝、锌、锡、铅等有色金属时，同焊接普通钢材相比，焊工可不采用安全措施。(     )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_157"},{"id":158,"type":"judge","stem":"焊件进行临时点固时严禁由配合焊工作业的人员进行。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_158"},{"id":159,"type":"judge","stem":"电焊钳过热后可以浸在水中冷却后使用。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_159"},{"id":160,"type":"judge","stem":"交流电焊机除应设置一般漏电保护以外，还应配装二次空载降压保护器。 (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_160"},{"id":161,"type":"judge","stem":"电焊机导线绝缘电阻可为0.8MΩ。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_161"},{"id":162,"type":"judge","stem":"手持式电动工具的负荷线应采用耐气候型橡皮护套铜芯软电缆，并且不得有接头，水平距离不宜大于3m。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_162"},{"id":163,"type":"judge","stem":"焊接承压状态的压力容器和装有剧毒、易燃、易爆物品的容器，应做好防毒措施。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_163"},{"id":164,"type":"judge","stem":"焊接设备应有完整的防护外壳，一、二次接线柱处应有保护罩。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_164"},{"id":165,"type":"judge","stem":"当预热焊件温度达150℃~700℃时，应设挡板隔离焊件发出的辐射热，焊接人员应穿戴粗布服装和绝缘鞋。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_165"},{"id":166,"type":"judge","stem":"使用氩弧焊时，操作人员应戴防毒面罩。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_166"},{"id":167,"type":"judge","stem":"使用点焊机进行作业时，气路、水冷系统应畅通。气体应保持干燥。排水温度不得超过50℃,排水量可根据水温调节。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_167"},{"id":168,"type":"judge","stem":"使用埋弧焊机作业，应及时排走焊接中产生的有害气体，在通风不良的室内或容器内作业时，应安装通风设备。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_168"},{"id":169,"type":"judge","stem":"气瓶每五年应检验一次，使用期不应超过20年。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_169"},{"id":170,"type":"judge","stem":"乙炔钢瓶使用时，应设有防止回火的安全装置(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_170"},{"id":171,"type":"judge","stem":"同时使用两种气体作业时，至少有一个气瓶应安装单向阀，防止气体倒灌。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_171"},{"id":172,"type":"judge","stem":"操作等离子切割机作业时，操作人员应站在上风处，并戴好防护面罩、电焊手套、帽子、滤膜防尘口罩和隔声耳罩。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_172"},{"id":173,"type":"judge","stem":"操作咬口机时，不得用手触碰转动中的辊轮，也不得用手送工件。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_173"},{"id":174,"type":"judge","stem":"操作小型台钻时，操作人员应按规定穿戴防护用品，并扎紧袖口。不得围围巾及戴手套。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_174"},{"id":175,"type":"judge","stem":"手动操作小型台钻进钻退钻时，当进钻困难时，可用管子套在手柄上加压进钻。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_175"},{"id":176,"type":"judge","stem":"喷浆机开机时，应先打开料桶开关，让石灰浆流入泵体内部后，再开动电动机带泵旋转。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_176"},{"id":177,"type":"judge","stem":"喷浆机作业后，应往料斗注入清水，开泵清洗直到水清为止再倒出泵内积水，清洗疏通喷头座及滤网，并将喷枪擦洗干净。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_177"},{"id":178,"type":"judge","stem":"混凝土切割机作业后，应清洗机身，擦干锯片，水箱内应留有三分之一的水，不得排放干净。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_178"},{"id":179,"type":"judge","stem":"使用混凝土切割机切割小块料时，应使用专用工具送料，不得直接用手推料。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_179"},{"id":180,"type":"judge","stem":"通风机风管安装不应妨碍人员行走及车辆通行，风管出风口距工作面宜为5m。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_180"},{"id":181,"type":"judge","stem":"泥浆泵启动前，吸水管、底阀及泵体内不得有水，压力表缓冲器上端应注满油。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_181"},{"id":182,"type":"judge","stem":"使用角向磨光机进行磨削作业时，应使砂轮与工件面保持15°〜30°的倾斜位置；切削作业时，砂轮不得倾斜，并不得横向摆动。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_182"},{"id":183,"type":"judge","stem":"使用I类电动工具时，应安装额定漏电动作电流不大于15mA.额定漏电动作时间不大于0.2s的防溅型漏电保护器。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_183"},{"id":184,"type":"judge","stem":"使用电剪时，作业前，应先根据钢板厚度调节刀头间隙量，最大剪切厚度不得大于铭牌标定值。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_184"},{"id":185,"type":"judge","stem":"击发时，应将射钉枪垂直压紧在工作面上。当两次扣动扳机，子弹不击发时，应立即退出射钉弹。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_185"},{"id":186,"type":"judge","stem":"使用射钉枪时，不得用手掌推压钉管和将枪口对准人。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_186"},{"id":187,"type":"judge","stem":"云（切）石机在使用过程中发生刀片卡死时，应立即停机，并快速退出刀片，重新对正后再切割。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_187"},{"id":188,"type":"judge","stem":"使用拉铆枪铆接时，可重复扣动扳机，直到铆钉被拉断为止，不得强行扭断或撬断。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_188"},{"id":189,"type":"judge","stem":"柴油发电机组可以与外电线路并列运行，不得采取电气隔离措施与外电线路互锁。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_189"},{"id":190,"type":"judge","stem":"当两台及以上柴油发电机组并列运行时，必须装设同步装置，且应在机组同步后再向负载供电(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_190"},{"id":191,"type":"judge","stem":"柴油机曲轴箱内机油量宜在机油尺上下刻度中间稍下位置。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_191"},{"id":192,"type":"judge","stem":"柴油发电机组应釆用电源中性点直接接地的三相四线制供电系统和独立设置的与原供电系统一致的接零保护系统。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_192"},{"id":193,"type":"judge","stem":"平地机的铲刀应能升降、倾斜、侧移、引出和180°回转，回转应平稳，不应有阻滞。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_193"},{"id":194,"type":"judge","stem":"土方机械的驾驶室门窗开关应自如，雨刮器、门锁应完好，玻璃不应有破损。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_194"},{"id":195,"type":"judge","stem":"Ⅰ类工具电源线中的绿/黄双色线在任何情况下只能用作保护接地线(PE)。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_195"},{"id":196,"type":"judge","stem":"手持电动工具电源线上的插头可以由专业电工进行拆除或调换。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_196"},{"id":197,"type":"judge","stem":"手持电动工具在发出或收回时,保管人员应进行一次日常检查;在使用前,使用者应进行日常检查。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_197"},{"id":198,"type":"judge","stem":"机械设备或设施的防雷引下线可利用该设备或设施的金属结构体，但应保证电气连接。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_198"},{"id":199,"type":"judge","stem":"机械设备上的避雷针(接闪器)长度应为1～2m。塔式起重机可不另设避雷针(接闪器)。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_199"},{"id":200,"type":"judge","stem":"塔式起重机、施工升降机、滑升模板的金属操作平台及需要设置避雷装置的物料提升机，除应连接保护接地导体外，还应与各自的接地装置相连接  （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_200"},{"id":201,"type":"judge","stem":"夯土机械的操作扶手必须绝缘。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_201"},{"id":202,"type":"judge","stem":"使用电焊机械焊接时必须穿戴防护用品。一般情况露天冒雨从事电焊作业。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_202"},{"id":203,"type":"judge","stem":"麻绳捆绑时，在物体的尖锐边角处应垫上保护性软物。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_203"},{"id":204,"type":"judge","stem":"钢丝绳可以作任意选用，且可超负荷使用。（     ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_204"},{"id":205,"type":"judge","stem":"化学纤维绳应远离明火和高温，但可在露天长期暴晒。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_205"},{"id":206,"type":"judge","stem":"电动卷扬机用完后，可以不切断电源，但要将控制器放到零位，用保险闸自动刹紧，并拉紧跑绳。    (   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_206"},{"id":207,"type":"judge","stem":"金属桅杆可分为钢管式和格构式。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_207"},{"id":208,"type":"judge","stem":"履带式起重机越野性能好，机动性好，可长距离转移并对道路无破坏性。     (   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_208"},{"id":209,"type":"judge","stem":"轮胎式起重机的安全技术要求与汽车式起重机的安全技术要求相仿。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_209"},{"id":210,"type":"judge","stem":"桅杆滑移法吊装是利用桅杆起重机提升滑轮组能够向上提升这一动作，设置尾排及其他索具配合，将立式静置工件吊装就位。    (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_210"},{"id":211,"type":"judge","stem":"当塔机吊重超过最大起重量并小于最大起重量的110％时，应停止提升方向的运行，但允许机构有下降方向的运动。    (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_211"},{"id":212,"type":"judge","stem":"高架物料提升机可以采用摩擦式卷扬机。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_212"},{"id":213,"type":"judge","stem":"塔式起重机起重力矩超过其相应幅度的规定值并小于规定值的110％时，起重力矩限制器应起作用使塔机停止下降方向及向臂根方向变幅的动作。        (   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_213"},{"id":214,"type":"judge","stem":"塔式起重机司机对任何人发出的紧急停止信号，均应服从。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_214"},{"id":215,"type":"judge","stem":"动臂式和尚未附着的自升式塔机，塔身上不得悬挂标语牌。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_215"},{"id":216,"type":"judge","stem":"用钢丝绳做物料提升机缆风绳时，直径不得小于9.3mm。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_216"},{"id":217,"type":"judge","stem":"施工升降机运行到最上层或最下层时，可以采用限位装置作为停止运行的控制开关。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_217"},{"id":218,"type":"judge","stem":"风力在六级以上时，塔机不得进行顶升作业。   （    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_218"},{"id":219,"type":"judge","stem":"塔式起重机的机体已经接地，其电气设备的外露可导电部分可不再与PE线连接。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_219"},{"id":220,"type":"judge","stem":"钢丝绳可以任意选用，且超负荷使用。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_220"},{"id":221,"type":"judge","stem":"塔式起重机司机年龄不应超过45周岁。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_221"},{"id":222,"type":"judge","stem":"施工现场装有2台以上塔式起重机时，高位起重机最高部件与低位起重机最低部件之间垂直距离不得小于2m。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_222"},{"id":223,"type":"judge","stem":"施工电梯卸料平台与梯笼最外侧之间距离不大于100mm。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_223"},{"id":224,"type":"judge","stem":"钢丝绳末端用绳夹固定时绳夹数量不得少于3个。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_224"},{"id":225,"type":"judge","stem":"起吊设备时，电动卷扬机卷筒上钢丝绳余留圈数应不少于3圈。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_225"},{"id":226,"type":"judge","stem":"使用滑轮的直径，通常不得小于钢丝绳直径的20倍。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_226"},{"id":227,"type":"judge","stem":"施工升降机吊笼内空净高度不得小于2米。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_227"},{"id":228,"type":"judge","stem":"钢丝绳防脱槽装置能够防止钢丝绳在传动过程中脱离滑轮槽而造成钢丝绳卡死或损坏。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_228"},{"id":229,"type":"judge","stem":"多塔作业时，处于高位的塔机（吊钩升至最高点）与低位塔机的垂直距离在任何情况下不得小于1.5米。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_229"},{"id":230,"type":"judge","stem":"每台起重机都应在适当的位置装设标牌，标牌应至少标明以下内容：制造商名称、产品名称和型号、主要性能参数、出厂编号、制造日期。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_230"},{"id":231,"type":"judge","stem":"人货两用施工升降机提升吊笼钢丝绳的安全系数不得小于12。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_231"},{"id":232,"type":"judge","stem":"塔吊吊钩危险断面磨损达原尺寸的5%即应报废。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_232"},{"id":233,"type":"judge","stem":"小车行程限位器设于起重臂两端，用来切断小车牵引机构的电路，防止小车越位。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_233"},{"id":234,"type":"judge","stem":"吊钩保险是防止起吊钢丝绳由于角度过大或挂钩不妥时，造成起吊钢丝绳脱钩的安全装置。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_234"},{"id":235,"type":"judge","stem":"多塔作业时，处于高位的塔机吊钩升至最高点与低位塔机的垂直距离在任何情况下不得小于5m。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_235"},{"id":236,"type":"judge","stem":"物料提升机防护棚搭设材料的强度应能承受1000N/㎡的均布荷载，也可采用30mm厚的木板架设或采用两层竹笆搭设，上下竹笆间的间距应不小于500mm。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_236"},{"id":237,"type":"judge","stem":"物料提升机在运行时，吊篮升降的工作钢丝绳突然发生断绳时，安全停靠装置应立即打开。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_237"},{"id":238,"type":"judge","stem":"物料提升机底层进料口防护棚搭设材料的强度应能承受800N/㎡的均布荷载。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_238"},{"id":239,"type":"judge","stem":"施工升降机的安全器只能在有效的标定期限内使用，有效标定期不超过1年。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_239"},{"id":240,"type":"judge","stem":"SC型建筑施工升降机的整机使用年限为8年。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_240"},{"id":241,"type":"judge","stem":"小车变幅的起重机，起升高度限位器应能保证在吊钩架顶部与小车架下端净距≥0.6m时，立即切断上升方向电源，吊钩起吊重物只有下降电源。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_241"},{"id":242,"type":"judge","stem":"群塔作业规定，固定式塔吊低位臂的端部与高位塔身不小于4m，高位塔吊的吊钩与低位塔吊的垂直距离不小于4m（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_242"},{"id":243,"type":"judge","stem":"当塔机吊重超过最大起重量并小于最大起重量的110%时，应停止提升方向的运行，但允许机构有下降方向的运动。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_243"},{"id":244,"type":"judge","stem":"遇六级及其以上风力应停止一切吊运作业。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_244"},{"id":245,"type":"judge","stem":"多塔作业时，处于高位的塔机吊钩升至最高点与低位塔机的垂直距离在任何情况下不得小于2m。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_245"},{"id":246,"type":"judge","stem":"钢丝绳在卷筒上保留圈数应大于5圈。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_246"},{"id":247,"type":"judge","stem":"起重量大于3吨的塔式起重机应设力矩限制器。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_247"},{"id":248,"type":"judge","stem":"塔式起重机安装高度大于30m的应设风速仪。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_248"},{"id":249,"type":"judge","stem":"超载限制器的作用之一是当塔机吊重超过最大起重量并小于最大起重量的 110%时,应停止提升方向的运行，但允许机构有下降方向的运动。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_249"},{"id":250,"type":"judge","stem":"当起重力矩大于相应工况下的额定值并小于该额定值的110%时，起重力矩限制器应能切断上升和幅度增大方向的电源，但机构可作下降和减小幅度方向的运动。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_250"},{"id":251,"type":"judge","stem":"塔式起重机加节后需进行附着的，应按照先顶升加节、后装附着装置的顺序进行,附着装置的位置和支撑点的强度应符合要求。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_251"},{"id":252,"type":"judge","stem":"塔式起重机拆卸时应先降节，后拆除附着装置。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_252"},{"id":253,"type":"judge","stem":"塔机可用吊钩直接挂吊物，严禁用塔机运送人员。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_253"},{"id":254,"type":"judge","stem":"电动卷扬机用完后，可以不切断电源，但要将控制器放到零位，用保险闸自动刹紧，并拦紧跑绳。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_254"},{"id":255,"type":"judge","stem":"履带式起重机操作灵活，使用方便，车身能360度回转，并且可以载荷行驶，越野性能好，机动性好，可长距离转移并对道路无破坏性。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_255"},{"id":256,"type":"judge","stem":"钢丝绳严禁采用打结方式系结吊物。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_256"},{"id":257,"type":"judge","stem":"滑轮、卷筒均应设有钢丝绳防脱装置；吊钩应设有钢丝绳防脱钩装置。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_257"},{"id":258,"type":"judge","stem":"当利用辅助起重设备安装、拆卸施工升降机时，应对辅助设备设置位置、锚固方法和基础承载能力等进行设计和验算。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_258"},{"id":259,"type":"judge","stem":"塔式起重机附墙架长度不满足现场施工需求的，施工现场可自行焊接加长使用。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_259"},{"id":260,"type":"judge","stem":"施工升降机安装时，安装单位的专业技术人员、专职安全生产管理人员应进行现场监督。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_260"},{"id":261,"type":"judge","stem":"每次加节完毕后，应对施工升降机导轨架的垂直度进行校正，且应按规定及时重新设置行程限位和极限限位，经验收合格后方能运行。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_261"},{"id":262,"type":"judge","stem":"塔式起重机使用时，起重臂和吊物下方严禁有人员停留；物件吊运时，严禁从人员上方通过。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_262"},{"id":263,"type":"judge","stem":"钢丝绳在卷筒上缠绕时，要逐圈紧密地排列整齐，不应错叠或离缝。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_263"},{"id":264,"type":"judge","stem":"作业中遇突发故障，应采取措施将吊物降落到安全地点，严禁吊物长时间悬挂在空中。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_264"},{"id":265,"type":"judge","stem":"根据《房屋市政工程生产安全重大事故隐患判定标准》，施工临时用电方面，特殊作业环境照明未按规定使用安全电压的，应判定为重大事故隐患。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_265"},{"id":266,"type":"judge","stem":"基坑侧壁出现漏水、流土时，应立即封堵或坑外快速注浆的方式进行堵漏，可立即恢复施工。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_266"},{"id":267,"type":"judge","stem":"建筑起重机械的安全装置应齐全、有效，禁止违规拆除、破坏。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_267"},{"id":268,"type":"judge","stem":"碎石机工作时，若石料卡住进料口，应用手扳动。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_268"},{"id":269,"type":"judge","stem":"吊钩危险断面的高度磨损量达到原尺寸的20%需要更换。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_269"},{"id":270,"type":"judge","stem":"隧道内施工使用以汽油为动力的机械设备时应制订相应的安全措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_270"},{"id":271,"type":"judge","stem":"汽车起重机按照分类属于轮胎式起重机。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_271"},{"id":272,"type":"judge","stem":"当混凝土未达到规定强度或已达到设计规定强度时，如需提前拆模或承受部分超设计荷载时，必须经过计算和监理工程师确认其强度能足够承受此荷载后，方可拆除。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_272"},{"id":273,"type":"judge","stem":"钢架施工时相邻的钢架应连接成整体。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_273"},{"id":274,"type":"judge","stem":"根据《建筑施工工具式脚手架安全技术规范》JGJ 202-2010，附着式升降脚手架的防坠落装置宜采用机械式的全自动装置或每次升降后重组的手动装置。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_274"},{"id":275,"type":"judge","stem":"瓦斯隧道两个作业面之间应串联通风。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_275"},{"id":276,"type":"judge","stem":"根据《建筑施工塔式起重机安装、使用、拆卸安全技术规程》JGJ196-2010，塔式起重机顶升过程中，不应该进行起升、回转等操作，可以进行变幅。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_276"},{"id":277,"type":"judge","stem":"施工升降机主要受力构件失去整体稳定性时不应修复，应报废。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_277"},{"id":278,"type":"judge","stem":"两台起重机共同起吊一货物时，必须有专人统一指挥，两台起重机性能、速度应相同，各自分担的载荷值，应小于一台起重机的额定总起重量的80%；其重物的重量不得超过两机起重量总和的80%。","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_278"},{"id":279,"type":"judge","stem":"吊装作业应设置缆风绳等软固定设施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_279"},{"id":280,"type":"judge","stem":"无轨运输进洞载物车辆车速不得大于8km/h，空车车速不得大于15km/h，出洞爬坡车速不得大于20km/h。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_280"},{"id":281,"type":"judge","stem":"暴风雪及台风暴雨后，应对高处作业安全设施逐一加以检查，发现有松动、变形、损坏或脱落等现象，应立即修理完善。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_281"},{"id":282,"type":"judge","stem":"对邻近的人与物有坠落危险性的其他竖向孔、洞口，均应加以防护，并有固定其位置的措施。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_282"},{"id":283,"type":"judge","stem":"防护棚搭设与拆除时，应设警戒区，并应派专人监护，可以上下同时拆除。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_283"},{"id":284,"type":"judge","stem":"攀登和悬空高处作业人员以及搭设高处作业安全设施的人员，必须经过上岗培训，并定期进行体格检查。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_284"},{"id":285,"type":"judge","stem":"临边防护栏杆中，钢管横杆及栏杆均采用符合要求的管材，以扣件或电焊固定。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_285"},{"id":286,"type":"judge","stem":"采用人字梯作业时，只有高级工可以站在梯子上移动梯子或在最顶层作业。  (   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_286"},{"id":287,"type":"judge","stem":"悬挑式钢平台的搁支点与上部拉结点，宜设置在脚手架等施工设施上。    (   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_287"},{"id":288,"type":"judge","stem":"结构施工自二层起，凡人员进出的通道口宜视情况搭设安全防护棚，高度超过24m的层次必须搭设安全防护棚。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_288"},{"id":289,"type":"judge","stem":"施工前，应逐级进行安全技术教育及交底，落实所有安全技术措施和人身防护用品，未经落实时不得进行施工。 (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_289"},{"id":290,"type":"judge","stem":"井架与施工用电梯和脚手架等与建筑物通道的两侧边，必须设防护栏杆。 (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_290"},{"id":291,"type":"judge","stem":"高处作业有重大危险源识别和控制清单就可以了。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_291"},{"id":292,"type":"judge","stem":"凡在坠落高度基准面2m以上（含2m）有可能坠落的高处进行的作业称高处作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_292"},{"id":293,"type":"judge","stem":"防护栏杆搭设，上杆离地高度为1-1.2m，下杆离地高度为0.5-0.6m。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_293"},{"id":294,"type":"judge","stem":"电梯井内没有安全平网，可每隔两层加设一道竹胶板防护。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_294"},{"id":295,"type":"judge","stem":"边长在150㎝以上的洞口，应在四周设防护栏杆，洞口下张设安全平网。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_295"},{"id":296,"type":"judge","stem":"高度超过24m的以上的交叉作业，凡人员进入的通道应设双层安全防护棚。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_296"},{"id":297,"type":"judge","stem":"移动式操作平台的面积不应超过15㎡。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_297"},{"id":298,"type":"judge","stem":"吊篮脚手架平台工作面的护栏不低于0.8m，其余部位不低于1.2m。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_298"},{"id":299,"type":"judge","stem":"吊篮脚手架平台底部四周必须安装高度不小于180mm的挡脚板，挡板与底板间距不大于5mm。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_299"},{"id":300,"type":"judge","stem":"吊篮脚手架的钢丝绳的安全系数不小于9倍的荷载。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_300"},{"id":301,"type":"judge","stem":"吊篮脚手架的安全锁有效期时间为2年。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_301"},{"id":302,"type":"judge","stem":"吊篮脚手架的电动葫芦提升机构一般应配两套独立的制动器，每套均可使带有额定荷载125%的吊篮平台停住。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_302"},{"id":303,"type":"judge","stem":"吊篮脚手架的静载试验按使用荷载125%进行检验。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_303"},{"id":304,"type":"judge","stem":"高处作业使用的安全带绳长限定在1.5-2m；如需接长，必须按规定加设缓冲器。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_304"},{"id":305,"type":"judge","stem":"安全帽的耐穿刺性能应能承受5kg钢锤自1m高处自由坠落的冲击。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_305"},{"id":306,"type":"judge","stem":"密目式安全网的耐穿性试验是用长6m、宽1.8m的密目网，紧绑在与地面倾斜45度的试验框架上，网面绷紧，将直径48-51mm，重5kg脚手架钢管，在距离框架中心3m的高度自由落下，脚手架钢管不贯穿密目式安全网。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_306"},{"id":307,"type":"judge","stem":"高层建筑每隔四层固定一道3m宽的水平安全网，网的接口处必须连接严密。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_307"},{"id":308,"type":"judge","stem":"楼梯口应设置1.2m高度双层防护栏杆，栏杆底部应设置不小于0.18m的挡脚板。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_308"},{"id":309,"type":"judge","stem":"边长为50-100cm的预留洞口，必须设置以扣件扣接钢管形成的网格，或采用贯穿与混凝土内的钢筋构成的防护网，并在其上满铺竹笆或脚手板。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_309"},{"id":310,"type":"judge","stem":"电梯井内每隔三层必须使用脚手板进行封闭，防止人员坠落时一落到底。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_310"},{"id":311,"type":"judge","stem":"临边防护必须设1.2m高的双层防护栏杆，栏杆立柱间距不得大于2.5m。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_311"},{"id":312,"type":"judge","stem":"凡在坠落高度基准面2m 以上(含2m )有可能坠落的高处进行的作业称为高处作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_312"},{"id":313,"type":"judge","stem":"立梯踏板上下间距以500mm 为宜,不得有缺档。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_313"},{"id":314,"type":"judge","stem":"使用直爬梯攀登作业时,攀登高度超过8m ,必须设置梯间平台。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_314"},{"id":315,"type":"judge","stem":"高处作业基础高度为15~30m,则坠落半径为4m。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_315"},{"id":316,"type":"judge","stem":"高处作业共分为四级, 15~30m高处作业分级为Ⅱ级。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_316"},{"id":317,"type":"judge","stem":"制作钢操作平台时，吊点上需设置四个经过验算的合格的吊环，吊环用Q235钢制作。钢平台两侧，要按规定设置固定的防护栏杆。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_317"},{"id":318,"type":"judge","stem":"电梯井内没有安全平网，可每隔三层加设一道竹胶板防护。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_318"},{"id":319,"type":"judge","stem":"非竖向洞口短边边长在25mm~500mm的洞口，应在四周设防护栏杆，洞口下张设安全平网。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_319"},{"id":320,"type":"judge","stem":"安全带应高挂低用，防止摆动和碰撞；安全带上的各种部件不得任意拆掉。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_320"},{"id":321,"type":"judge","stem":"禁止在未固定、无防护设施的构件及管道上进行作业或通行。(    )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_321"},{"id":322,"type":"judge","stem":"悬挑式操作平台的搁置点、拉结点、支撑点应设置在稳定的主体结构上，且应可靠连接。(    )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_322"},{"id":323,"type":"judge","stem":"当需采用平网进行防护时，不能使用密目式安全立网代替平网使用。(    )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_323"},{"id":324,"type":"judge","stem":"移动式操作平台在移动时，操作平台上的人应蹲下并手扶防护栏杆。(     )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_324"},{"id":325,"type":"judge","stem":"双层作业时，应设置隔离措施和在高处作业点的下方设置防护。各种拆除作业（如钢模板、脚手架等）上面拆除时下面不得同时进行清整。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_325"},{"id":326,"type":"judge","stem":"高处作业可以在未固定的脚手架上作业；人员可以在不稳定的结构上快速通过。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_326"},{"id":327,"type":"judge","stem":"高处作业施工前，应检查高处作业的安全标志、安全设施、工具、仪表、防火设施、电气设施和设备，确认其完好，方可进行施工。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_327"},{"id":328,"type":"judge","stem":"高处作业攀登用具必须牢固可靠。梯子不得垫高使用，梯脚底部应有防滑措施，上端应有固定措施；折梯使用时，应有可靠的拉撑措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_328"},{"id":329,"type":"judge","stem":"必要时，可以使用起重机进行斜拉、斜吊，可以在重物上堆放或悬挂零星物件。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_329"},{"id":330,"type":"judge","stem":"高处作业应设置可靠扶梯，作业人员应沿着扶梯上下，不得沿着立杆与栏杆攀。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_330"},{"id":331,"type":"judge","stem":"受到严重冲击的安全带，外形未变可以使用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_331"},{"id":332,"type":"judge","stem":"当临边的外侧面临街道时，除防护栏杆外，敞口立面必须采取满挂安全网或其他可靠措施作全封闭处理。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_332"},{"id":333,"type":"judge","stem":"由于上方施工可能坠落物件或处于起重机把杆回转范围之内的通道，在其受影响范围内，必须搭设顶部能防止穿透的双层防护。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_333"},{"id":334,"type":"judge","stem":"施工现场，常见的楼梯口、门窗口、电梯井口、预留洞口通常称为“四口”。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_334"},{"id":335,"type":"judge","stem":"拆模板高处作业，应在支模架上作业，系好安全带。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_335"},{"id":336,"type":"judge","stem":"一般塑料安全帽的使用期不超过2年半，到期后即报废。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_336"},{"id":337,"type":"judge","stem":"当遇有4级以上强风、浓雾、沙尘暴等恶劣气候，不得进行露天攀登与悬空高处作业。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_337"},{"id":338,"type":"judge","stem":"坠落高度基准面1.8m 及以上进行临边作业时，应在空一侧设置防护栏杆并采用密目或工具式栏板封闭。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_338"},{"id":339,"type":"judge","stem":"当非垂直洞口短边边长为25㎜～500㎜时，应采用专项设计盖板覆盖，并应采取固定措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_339"},{"id":340,"type":"judge","stem":"电梯井口应设置防护门，其高度不应小于1.5m。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_340"},{"id":341,"type":"judge","stem":"安全网作防护层必须封挂严密牢靠，特殊情况可采用立网代替平网使用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_341"},{"id":342,"type":"judge","stem":"高处作业点下方必须设安全网。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_342"},{"id":343,"type":"judge","stem":"安全带的金属配件必须是普通碳素钢或是铝合金。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_343"},{"id":344,"type":"judge","stem":"当建筑物高度大于24m、并采用木板搭设时，应搭设双层防护棚，两层防护棚的间距不应小于800mm。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_344"},{"id":345,"type":"judge","stem":"墙面等处的竖向洞口低于80cm的应加设1.0m高的临时护栏。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_345"},{"id":346,"type":"judge","stem":"当梯子需接长使用时，应有可靠的连接措施，接头不得超过1处。连接后梯梁的强度，不应低于单梯梯梁的强度。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_346"},{"id":347,"type":"judge","stem":"当绑扎钢筋和安装钢筋骨架需悬空作业时，应搭设脚手架和上下通道，不得攀爬钢筋骨架。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_347"},{"id":348,"type":"judge","stem":"当绑扎立柱和墙体钢筋时，不得站在钢筋骨架上或攀登骨架作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_348"},{"id":349,"type":"judge","stem":"钢结构或装配式混凝土结构安装作业层应设置供作业人员系挂安全带的安全绳。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_349"},{"id":350,"type":"judge","stem":"高处作业现场所有可能坠落的物件均应预先撤除或固定。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_350"},{"id":351,"type":"judge","stem":"操作平台或脚手架作业层当采用冲压钢脚手板时，板面冲孔内切圆直径应小于30mm。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_351"},{"id":352,"type":"judge","stem":"正常使用的安全帽在使用期限内不能因材料原因导致防护功能失效。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_352"},{"id":353,"type":"judge","stem":"当安全帽配有附件（如防护面屏、护听器等）时，附件应不影响安全帽的佩戴稳定性，同时不影响其正常防护功能。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_353"},{"id":354,"type":"judge","stem":"安全带标识应固定于系带。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_354"},{"id":355,"type":"judge","stem":"土钉墙应按每层土钉及混凝土面层分层设置、分层开挖基坑的步序施工。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_355"},{"id":356,"type":"judge","stem":"当支护结构构件强度达到开挖阶段的设计强度的90%时，方可向下开挖。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_356"},{"id":357,"type":"judge","stem":"采用锚杆或支撑的支护结构，在未达到设计规定的拆除条件时，严禁拆除锚杆或支撑。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_357"},{"id":358,"type":"judge","stem":"基坑周边施工材料、设施或车辆荷载严禁超过设计要求的地面荷载限值。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_358"},{"id":359,"type":"judge","stem":"支护结构施工与基坑开挖期间，支护结构达到设计强度要求前，严禁在设计预计的滑裂面范围内堆载；临时土石方的堆放应进行包括自身稳定性、邻近建筑物地基和基坑稳定性验算。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_359"},{"id":360,"type":"judge","stem":"地下连续墙施工中，钢筋笼吊装前必须对钢筋笼进行全面检查，防止有剩余的钢筋断头、焊接接头等遗留在钢筋笼上。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_360"},{"id":361,"type":"judge","stem":"对安全等级为一级的基坑工程，应先进行坑内土体加固施工，再进行基坑围护施工。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_361"},{"id":362,"type":"judge","stem":"基坑周边必须进行有效防护，并设置明显的警示标志；基坑周边要设置堆放物料的限重牌，严禁堆放大量的物料。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_362"},{"id":363,"type":"judge","stem":"土石方工程应编制专项施工安全方案，并应严格按照方案实施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_363"},{"id":364,"type":"judge","stem":"爆破警戒范围由监理单位确定。在危险区边界，应设有明显标志，并派出警戒人员。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_364"},{"id":365,"type":"judge","stem":"爆破后应检查有无盲炮及其他险情。当有盲炮时，应立即处理，同时在现场设立危险标志，处理完成后要及时上报。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_365"},{"id":366,"type":"judge","stem":"开挖深度超过1.5m的基坑周边必须安装防护栏杆。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_366"},{"id":367,"type":"judge","stem":"基坑防护栏杆高度不应低于1.2m，立杆间距不宜大于1.8m。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_367"},{"id":368,"type":"judge","stem":"基坑支护结构必须在达到设计要求的强度后，方可开挖下层土方，严禁提前开挖和超挖。施工过程中，严禁设备或重物碰撞支撑、腰梁、锚杆等基坑支护结构，亦不得在支护结构上放置或悬挂重物。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_368"},{"id":369,"type":"judge","stem":"食堂必须有卫生许可证，炊事人员可不持身体健康证上岗。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_369"},{"id":370,"type":"judge","stem":"移动式操作平台载人移动时，必须有可靠的防护措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_370"},{"id":371,"type":"judge","stem":"深基坑开挖过程中必须进行基坑变形监测，发现异常情况应及时采取措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_371"},{"id":372,"type":"judge","stem":"土方开挖过程中，应定期对基坑及周边环境进行巡视，随时检查基坑位移（土体裂缝）、倾斜、土体及周边道路沉陷或隆起、地下水涌出、管线开裂、不明气体臂出和基坑防护栏杆的安全性等。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_372"},{"id":373,"type":"judge","stem":"边坡开挖施工区域一般不需要设置临时排水及防雨措施，特殊情况应按设计要求设置。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_373"},{"id":374,"type":"judge","stem":"土石方开挖应按设计要求自上而下分层实施，先开挖坡脚后开挖坡顶。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_374"},{"id":375,"type":"judge","stem":"在挖方的上侧和回填土尚未压实或临时边坡不稳定的地段不得搭建临时建筑，停放、检修施工机械时间不得超过24小时。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_375"},{"id":376,"type":"judge","stem":"山区土石方挖填方工程严禁在雨期施工。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_376"},{"id":377,"type":"judge","stem":"基坑施工前应编制专项施工方案，基坑支护结构应经监测单位确定。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_377"},{"id":378,"type":"judge","stem":"当开挖深度较大并存在边坡塌方危险时，应按监理要求进行支护。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_378"},{"id":379,"type":"judge","stem":"基坑钢支撑吊装就位时，基坑内严禁人员入内，并应采取有效的防下坠措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_379"},{"id":380,"type":"judge","stem":"喷射混凝土支护时，喷嘴不得面对有人方向。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_380"},{"id":381,"type":"judge","stem":"基坑支护用锚杆或锚索施工前应进行现场抗拉拔试验，施工完成后应进行验收。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_381"},{"id":382,"type":"judge","stem":"基坑支护面上方的锚杆或锚索、土钉、支撑必须在达到设计强度90%以上后，方可开挖下层土方，严禁提前开挖和超挖。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_382"},{"id":383,"type":"judge","stem":"基坑开挖应按设计和专项施工方案要求分层、分段、限时、均衡、不对称开挖。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_383"},{"id":384,"type":"judge","stem":"当利用基坑支撑兼作施工作业平台或施工栈桥时，上部机械设备的荷载不应包括在设计允许范围内。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_384"},{"id":385,"type":"judge","stem":"基坑边堆置土、料具等荷载不得超出基坑支护设计允许范围。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_385"},{"id":386,"type":"judge","stem":"基坑监测的时间间隔应根据监测方案及施工进度确定，当监测结果变化速率较大时，应加大观测频率。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_386"},{"id":387,"type":"judge","stem":"当基坑监测值达到所规定的报警值时，应停止施工，查明原因，采取补救措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_387"},{"id":388,"type":"judge","stem":"施工栈桥与作业平台搭设前无需编制专项施工方案，但应按要求编制安全保证措施和消防防护措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_388"},{"id":389,"type":"judge","stem":"施工栈桥与作业平台搭设前应编制完整的设计文件，并应对施工栈桥和作业平台结构、构件、地基基础进行设计，图纸和计算书应齐全。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_389"},{"id":390,"type":"judge","stem":"桥梁墩柱柱头应按专项施工方案要求作加强处理，并应与上部横梁、下部基础紧密接触、连接牢固。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_390"},{"id":391,"type":"judge","stem":"在施工栈桥与作业平台入口处应悬挂安全使用规程。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_391"},{"id":392,"type":"judge","stem":"施工栈桥与作业平台应设置行车限速、限载、防人员触电及落水等安全警示标志。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_392"},{"id":393,"type":"judge","stem":"通航水域施工栈桥与作业平台的临边栏杆应设置反光设施，边角处应设置黄色警示灯。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_393"},{"id":394,"type":"judge","stem":"通过施工栈桥的电缆应绝缘良好，并应在施工栈桥的正中置固定电缆的支架。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_394"},{"id":395,"type":"judge","stem":"通航水域的施工栈桥与作业平台应设置确保结构不会被船舶碰撞的防撞桩。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_395"},{"id":396,"type":"judge","stem":"猫道的专项施工方案应组织专家论证。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_396"},{"id":397,"type":"judge","stem":"风力大于6级时，不得进行移动模架施工作业，所有支腿均应处于锚固和锁定状态，外模板应闭合。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_397"},{"id":398,"type":"judge","stem":"悬臂施工挂篮的总重量应控制在设计规定限重之内。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_398"},{"id":399,"type":"judge","stem":"悬臂施工挂篮施工中，桥墩两侧挂篮应对称、平稳移动。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_399"},{"id":400,"type":"judge","stem":"矿山法隧道专项施工方案编制前应对工程周边环境进行核查，并应进行安全评估。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_400"},{"id":401,"type":"judge","stem":"盾构法隧道专项施工方案及重要部位、工序的专项施工方案应进行审核、审批。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_401"},{"id":402,"type":"judge","stem":"建设单位对因建设工程施工可能造成损害的毗邻建筑物、构筑物和地下管线等，应当采取专项防护措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_402"},{"id":403,"type":"judge","stem":"土体经过挖掘后，组织遭受破坏，体积减少的性质称为土的可松性。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_403"},{"id":404,"type":"judge","stem":"盾构机组装前，可以视情况对推进千斤顶、拼装机、调节千斤顶进行试验验收。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_404"},{"id":405,"type":"judge","stem":"流砂的发生与动水压力有关，动水压力系指地下水在渗流时受到土颗粒的阻力，同时水对相应地产生一种反作用力，这一反作用力就称为动水压力。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_405"},{"id":406,"type":"judge","stem":"当动水力等于或大于土的浸水重度，则土的颗粒失去自重，处于悬浮状态，此时土的抗剪强度为零，土颗粒就随着渗流的水起流动，这种现象就称“流砂”。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_406"},{"id":407,"type":"judge","stem":"锚杆可用钢筋或钢丝绳，一端固定在桩顶的腰梁(导梁)上，另一端固定在锚碇上，其长度应保证锚碇在土的破坏棱体以外。    (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_407"},{"id":408,"type":"judge","stem":"挡土墙的作用主要用来维护土体边坡的稳定，防止坡体的滑移和土边坡的坍塌。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_408"},{"id":409,"type":"judge","stem":"基坑(槽)施工中一般可不防止地面水流入坑沟内。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_409"},{"id":410,"type":"judge","stem":"人工开挖土方时，两个人操作间距应保持1-2m，并应自上而下逐层挖掘。(    )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_410"},{"id":411,"type":"judge","stem":"模板支架结构经设计计算并编制专项施工方案后才能搭设。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_411"},{"id":412,"type":"judge","stem":"同一模板支架可以采用不同材料搭设。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_412"},{"id":413,"type":"judge","stem":"规范要求模板扫地杆应按纵向设置。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_413"},{"id":414,"type":"judge","stem":"模板支架柱对接时，立柱应交错布置，两根立柱的接头应设置在同步内。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_414"},{"id":415,"type":"judge","stem":"现浇多层、高层房屋或构筑物，安装上层模板及支架时，上、下层支架的上下立柱对准即可，不用铺设垫板。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_415"},{"id":416,"type":"judge","stem":"模板支架搭设完毕，经验收即可使用。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_416"},{"id":417,"type":"judge","stem":"当采用扣件式钢管做立柱支撑时，可以将上段钢管立柱与下段钢管立柱错开固定在水平拉杆上。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_417"},{"id":418,"type":"judge","stem":"模板支架工程在大风地区或大风季节施工时，模板应有抗风的临时加固措施。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_418"},{"id":419,"type":"judge","stem":"扣件式钢管模板支架立杆底部通常应设置底座、通长木垫板、钢柱脚。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_419"},{"id":420,"type":"judge","stem":"多排扣件式钢管模板支架，四周应设通长竖向剪刀撑，中间纵横方向每隔4-5个立杆间距、5-7m应设置一道竖向剪刀撑。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_420"},{"id":421,"type":"judge","stem":"模板支架基础应符合坚实、平整、承载力符合设计要求、能承受支架上部全部荷载等要求。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_421"},{"id":422,"type":"judge","stem":"模板支架立柱底部应设置底座、垫板、大横杆。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_422"},{"id":423,"type":"judge","stem":"纵向扫地杆应采用直角扣件固定在距钢管底端不大于 200mm 处的立杆上，横向扫地杆应采用直角扣件固定在紧靠纵向扫地杆下方的立杆上。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_423"},{"id":424,"type":"judge","stem":"立杆基础不在同一高度上时必须将高处的纵向扫地杆向低处延长两跨与立杆固定，高低差不应大于1m(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_424"},{"id":425,"type":"judge","stem":"靠边坡上方的立杆轴线到边坡的距离不应小于1m。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_425"},{"id":426,"type":"judge","stem":"模板支架搭设前应满足模板支架搭设应编制专项施工方案、结构设计应进行计算、专项方案应按规定进行审核、审批等要求。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_426"},{"id":427,"type":"judge","stem":"模板支撑架的可调底座、可调托撑螺杆伸出长度不应超过400mm。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_427"},{"id":428,"type":"judge","stem":"模板支架可调托撑插入立杆内的长度不得小于150mm。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_428"},{"id":429,"type":"judge","stem":"模板支架水平杆接长时对接、搭接应符合两根相邻纵向水平杆的接头不宜设置在同步或同跨内，不同步或不同跨两个相邻接头在水平方向错开的距离不应小于500mm。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_429"},{"id":430,"type":"judge","stem":"模板支架水平杆接长时对接、搭接时搭接长度不应小于1m，应等距离设置3个旋转扣件固定，端部扣件盖板边缘至搭接水平杆杆端的距离不应小于100mm。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_430"},{"id":431,"type":"judge","stem":"模板支架主节点横向水平杆主节点处必须设置一根横向水平杆，用直角扣件扣接且严禁拆除，主节点两个直角扣件的中心距不应大于150mm。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_431"},{"id":432,"type":"judge","stem":"模板支架每道剪刀撑宽度不应小于6跨，且不应小于8m，剪刀撑斜杆与地面倾角宜在45~60之间。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_432"},{"id":433,"type":"judge","stem":"爬模装置的安装、操作、拆除应在专业厂家指导下进行，专业操作人员应进行爬模施工安全、技术培训，合格后方可上岗操作。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_433"},{"id":434,"type":"judge","stem":"操作平台与地面之间应有可靠的通讯联络。爬升和拆除过程中应分工明确、各负其责，应实行统一指挥、规范指令。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_434"},{"id":435,"type":"judge","stem":"对后退进行清理的外墙模板应及时恢复停放在原合模位置，并应临时拉接固定；架体爬升时，模板距结构表面不应大于300mm。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_435"},{"id":436,"type":"judge","stem":"爬模装置拆除时，参加拆除的人员可以不系安全带进行操作。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_436"},{"id":437,"type":"judge","stem":"滑模施工时应根据施工要求和滑模总载荷，合理选用千斤顶型号和配备台数，可以不按千斤顶型号选用相应的爬杆和滑升机件。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_437"},{"id":438,"type":"judge","stem":"滑模施工时上控制室作业人员必须小心谨慎，罐笼上、下时不得碰撞鼓筒。罐笼上下物件、上下人员时必须观察清楚，确定操作完毕，方可起动。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_438"},{"id":439,"type":"judge","stem":"铝模建筑混凝土终凝后8小时，可拆除竖向模板。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_439"},{"id":440,"type":"judge","stem":"铝合金模板体快拆体系由模板系统、支撑系统、紧固系统及附件系统组成。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_440"},{"id":441,"type":"judge","stem":"大模板工程中钢吊环、操作平台架挂钩等构件应采用冷加工成型。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_441"},{"id":442,"type":"judge","stem":"碗扣式钢管脚手架连墙件应在双排脚手架拆到该层时方可拆除，但若外墙装饰要求可提前拆除。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_442"},{"id":443,"type":"judge","stem":"碗扣式钢管脚手架连墙件必须随双排脚手架升高及时在规定的位置处设置，严禁随意拆除。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_443"},{"id":444,"type":"judge","stem":"碗扣式钢管脚手架搭设模板支撑架时，当周围有主体结构时，应设置连墙件。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_444"},{"id":445,"type":"judge","stem":"双排脚手架的搭设应分阶段进行，每段搭设完后应做好检查记录，待搭设到总高度时应做验收记录。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_445"},{"id":446,"type":"judge","stem":"碗扣式钢管脚手架搭设双排脚手架时，脚手架基础必须按专项施工方案进行施工，按基础承载力要求进行验收。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_446"},{"id":447,"type":"judge","stem":"双排脚手架及模板支撑架施工前必须编制专项施工方案，并经批准后，方可实施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_447"},{"id":448,"type":"judge","stem":"碗扣式钢管脚手架搭设双排脚手架时，当双排脚手架设置门洞时，应在门洞上部架设专用梁，门洞两侧立杆应加设斜杆。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_448"},{"id":449,"type":"judge","stem":"碗扣式钢管脚手架搭设模板支撑架时，立杆上端包括可调螺杆伸出顶层水平杆的长度不得大于0.8m。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_449"},{"id":450,"type":"judge","stem":"碗扣式钢管脚手架搭设双排脚手架时，连墙件应呈水平设置，当不能呈水平设置时，与脚手架连接的一端应向上斜连接。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_450"},{"id":451,"type":"judge","stem":"采用钢板热冲压整体成型的下碗扣，钢板板材厚度不得小于8mm。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_451"},{"id":452,"type":"judge","stem":"高宽比大于3的盘扣式支撑架应采取与既有结构进行刚性连接等抗倾覆措施。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_452"},{"id":453,"type":"judge","stem":"盘扣式脚手架重型的立杆钢管外径应为48.3mm。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_453"},{"id":454,"type":"judge","stem":"盘扣式脚手架标准型的立杆钢管外径应为48.3mm。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_454"},{"id":455,"type":"judge","stem":"承插型盘扣式钢管支架的检验分出厂检验和型式检验。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_455"},{"id":456,"type":"judge","stem":"当立杆不考虑风荷载时，应按承受轴向荷载杆件计算。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_456"},{"id":457,"type":"judge","stem":"当立杆考虑风荷载时，应按压弯杆件计算。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_457"},{"id":458,"type":"judge","stem":"当脚手架搭设在结构楼面上时，不需要对支承架体的楼面结构进行承载力验算。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_458"},{"id":459,"type":"judge","stem":"拆除作业应按先装后拆、后装先拆的原则进行，应从顶层开始、逐层向下进行，不得上下同时作业，不应抛掷。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_459"},{"id":460,"type":"judge","stem":"支撑架搭设完成后应对架体进行验收，并应确认符合专项施工方案要求后再进入下道工序施工。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_460"},{"id":461,"type":"judge","stem":"失稳坍塌破坏是支撑架的主要破坏形式。(   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_461"},{"id":462,"type":"judge","stem":"当电源离手持电动工具操作点距离较远而电源线长度不够时，可由专业电工接长或拆换手持电动工具的电源线。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_462"},{"id":463,"type":"judge","stem":"安装、巡检、维修或拆除临时用电设备和线路，必须由电工完成。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_463"},{"id":464,"type":"judge","stem":"暂时停用设备的开关箱一般应分断电源隔离开关，并应关门上锁。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_464"},{"id":465,"type":"judge","stem":"移动电气设备时，必须经电工切断电源并做妥善处理后进行。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_465"},{"id":466,"type":"judge","stem":"临时用电工程应定期检查。定期检查时，应复查接地电阻值和绝缘电阻值。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_466"},{"id":467,"type":"judge","stem":"临时用电工程定期检查应按分部、分项工程进行，对安全隐患必须及时处理，无需履行复查验收手续。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_467"},{"id":468,"type":"judge","stem":"在建工程不得在外电架空线路正下方施工、搭设作业棚、建造生活设施或堆放构件、架具、材料及其他杂物等。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_468"},{"id":469,"type":"judge","stem":"施工现场开挖沟槽边缘与外电埋地电缆沟槽边缘之间的距离不得小于0.5m。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_469"},{"id":470,"type":"judge","stem":"在外电架空线路附近开挖沟槽时，一般应同有关部门采取加固措施，防止外电架空线路电杆倾斜、悬倒。 （   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_470"},{"id":471,"type":"judge","stem":"电气设备设置场所应能避免物体打击和机械损伤，否则应做防护处置。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_471"},{"id":472,"type":"judge","stem":"施工现场的临时用电电力系统严禁利用大地做相线或零线。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_472"},{"id":473,"type":"judge","stem":"城防、人防、隧道、通道等潮湿或条件特别恶劣施工现场的电气设备必须采用保护接零。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_473"},{"id":474,"type":"judge","stem":"在TN系统中，保护零线每一处重复接地装置的接地电阻值不应大于4Ω。在工作接地电阻值允许达到4Ω的电力系统中，所有重复接地的等效电阻值不应大于4Ω。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_474"},{"id":475,"type":"judge","stem":"施工现场内所有防雷装置的冲击接地电阻值不得大于30Ω。 (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_475"},{"id":476,"type":"judge","stem":"配电室和控制室应设置通风设施或空调设施，并应采取防止雨雪侵入和小动物进入的措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_476"},{"id":477,"type":"judge","stem":"配电室应保持整洁，紧急情况可以堆放一些物品，做好台账。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_477"},{"id":478,"type":"judge","stem":"架空线导线截面的选择，按机械强度要求，绝缘铜线截面不小于10mm²，绝缘铝线截面不小于16mm²。 （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_478"},{"id":479,"type":"judge","stem":"施工现场用电工程的二级漏电保护系统中，漏电保护器可以分设于分配电箱和开关箱中。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_479"},{"id":480,"type":"judge","stem":"配电箱和开关箱中的N、PE接线端子板必须分别设置。其中N端子板与金属箱体绝缘；PE端子板与金属箱体电气连接。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_480"},{"id":481,"type":"judge","stem":"配电箱和开关箱中的隔离开关可采用普通断路器。（     ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_481"},{"id":482,"type":"judge","stem":"配电箱和开关箱中的隔离开关应采用具有可见分断点的断路器。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_482"},{"id":483,"type":"judge","stem":"需要三相四线制配电的电缆线路可以采用四芯电缆外加一根绝缘导线替代。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_483"},{"id":484,"type":"judge","stem":"用电设备的开关箱中设置了漏电保护器以后，其外露可导电部分可不需连接PE线。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_484"},{"id":485,"type":"judge","stem":"五芯电缆必须包含淡蓝、绿/黄二种颜色绝缘芯线。淡蓝色芯线必须用作L线；绿/黄双色芯线必须用作PE线，严禁混用。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_485"},{"id":486,"type":"judge","stem":"配电系统应设置配电柜或总配电箱、开关箱，实行两级配电。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_486"},{"id":487,"type":"judge","stem":"金属电器安装板与金属箱体应做电气连接。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_487"},{"id":488,"type":"judge","stem":"配电箱、开关箱外形结构应能防雨、防尘。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_488"},{"id":489,"type":"judge","stem":"总配电箱和开关箱中剩余电流动作保护器的极数和线数必须与其负荷侧载荷的相数和线数一致。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_489"},{"id":490,"type":"judge","stem":"配电箱、开关箱的电源进线端应采用插头和插座做活动连接。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_490"},{"id":491,"type":"judge","stem":"配电箱、开关箱箱门应配锁，并应由作业人员负责。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_491"},{"id":492,"type":"judge","stem":"配电箱、开关箱内不得放置任何杂物，并应保持整洁。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_492"},{"id":493,"type":"judge","stem":"配电箱、开关箱内的电器配置和接线严禁随意改动。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_493"},{"id":494,"type":"judge","stem":"配电箱、开关箱的进线和出线在强度允许情况下可以承受外力，但严禁与金属尖锐断口、强腐蚀介质和易燃易爆物接触。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_494"},{"id":495,"type":"judge","stem":"停电后，操作人员需及时撤离的施工现场，应装设自备电源的应急照明。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_495"},{"id":496,"type":"judge","stem":"施工现场发生火灾或意外事件时，供人员安全撤离危险区域并到达安全地点或安全地带所经的路径称为临时疏散通道。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_496"},{"id":497,"type":"judge","stem":"所有供人员和设备实施灭火救援作业的场地称为临时消防救援场地。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_497"},{"id":498,"type":"judge","stem":"临时用房、临时设施的布置宜满足现场防火、灭火及人员安全疏散的要求，若施工现场确实无法满足时，经过项目经理批准可以不按照防火、灭火要求进行布置。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_498"},{"id":499,"type":"judge","stem":"施工现场临时办公、生活、生产、物料存贮等功能区宜相对独立布置。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_499"},{"id":500,"type":"judge","stem":"可燃材料堆场及其加工场、易燃易爆危险品库房经过处理，可以布置在架空电力线下。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_500"},{"id":501,"type":"judge","stem":"施工现场周边道路满足消防车通行及灭火救援要求时，施工现场内可不设置临时消防车道。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_501"},{"id":502,"type":"judge","stem":"临时消防车道的左侧应设置消防车行进路线指示标识。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_502"},{"id":503,"type":"judge","stem":"临时用房和在建工程应采取可靠的防火分隔和安全疏散等防火技术措施。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_503"},{"id":504,"type":"judge","stem":"根据《建设工程施工现场消防安全技术规范》规定，宿舍、办公用房疏散楼梯的净宽度不应大于疏散走道的净宽度。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_504"},{"id":505,"type":"judge","stem":"发电机房、变配电房、厨房操作间、锅炉房、可燃材料库房及易燃易爆危险品库房的防火设计燃烧性能等级应为B1级。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_505"},{"id":506,"type":"judge","stem":"根据《建设工程施工现场消防安全技术规范》规定，在建工程作业场所的临时疏散通道不能利用在建工程施工完毕的水平结构、楼梯。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_506"},{"id":507,"type":"judge","stem":"临时疏散通道不宜采用爬梯，确需采用时，经过安全员批准方可。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_507"},{"id":508,"type":"judge","stem":"既有建筑进行扩建、改建施工时，若场地有限，可先不划分施工区和非施工区，待具备条件后按照要求进行划分。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_508"},{"id":509,"type":"judge","stem":"根据《建设工程施工现场消防安全技术规范》规定，非施工区内的消防设施应完好和有效，疏散通道应保持畅通，并应落实日常值班及消防安全管理制度。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_509"},{"id":510,"type":"judge","stem":"根据《建设工程施工现场消防安全技术规范》规定，施工区的消防安全应配有兼职人员值守，发生火情应能立即处置。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_510"},{"id":511,"type":"judge","stem":"作业场所应设置明显的疏散指示标志，其指示方向应指向最近的临时疏散通道入口。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_511"},{"id":512,"type":"judge","stem":"根据《建设工程施工现场消防安全技术规范》规定，作业层的醒目位置应设置安全疏散示意图。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_512"},{"id":513,"type":"judge","stem":"施工现场可根据情况设置灭火器、临时消防给水系统和应急照明等临时消防设施。（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_513"},{"id":514,"type":"judge","stem":"临时消防设施应与在建工程的施工同步设置。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_514"},{"id":515,"type":"judge","stem":"在建工程不能利用已具备使用条件的永久性消防设施作为临时消防设施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_515"},{"id":516,"type":"judge","stem":"根据《建设工程施工现场消防安全技术规范》规定，地下工程的施工作业场所必须配备防毒面具。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_516"},{"id":517,"type":"judge","stem":"设置室内消防给水系统的在建工程，应设置消防水泵接合器。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_517"},{"id":518,"type":"judge","stem":"设置临时室内消防给水系统的在建工程，每隔三层应设置室内消火栓接口及消防软管接口。(    )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_518"},{"id":519,"type":"judge","stem":"高层设置中转水池的，中转水池的有效容积不应少于10m³，上、下两个中转水池的高差不宜超过100m。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_519"},{"id":520,"type":"judge","stem":"临时消防给水系统的给水压力应满足消防水枪充实水柱长度不小于10m的要求；给水压力不能满足要求时，应设置消火栓泵，消火栓泵不应少于2台，且应互为备用；消火栓泵宜设置自动启动装置。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_520"},{"id":521,"type":"judge","stem":"严寒和寒冷地区的现场临时消防给水系统应采取防冻措施。（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_521"},{"id":522,"type":"judge","stem":"施工单位应依据灭火及应急疏散预案，不定期开展灭火及应急疏散的演练。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_522"},{"id":523,"type":"judge","stem":"施工单位应做好并保存施工现场消防安全管理的相关文件和记录，并应建立现场消防安全管理档案。(    )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_523"},{"id":524,"type":"judge","stem":"施工产生的可燃、易燃建筑垃圾或余料，可以长期在指定位置堆放。（）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_524"},{"id":525,"type":"judge","stem":"易燃易爆危险品应分类专库储存，库房内应通风良好，并应设置严禁明火标志。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_525"},{"id":526,"type":"judge","stem":"门式脚手架配件与门架配套，不同型号的门架与配件严禁混合使用（     ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_526"},{"id":527,"type":"judge","stem":"门式脚手架的水平加固杆应靠近门架横杆设置，应采用扣件与相关门架立杆扣紧（     ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_527"},{"id":528,"type":"judge","stem":"门式脚手架剪刀撑设置宽度应为4-6跨之间，且应在6-9m之间（     ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_528"},{"id":529,"type":"judge","stem":"门式脚手架剪刀撑斜杆的倾角应为45°-60°之间。（     ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_529"},{"id":530,"type":"judge","stem":"作业人员上下门式脚手架的斜梯宜采用挂扣式钢梯，并应采用Z字型设置，一个梯段宜跨越一步再进行转折（     ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_530"},{"id":531,"type":"judge","stem":"门式脚手架的内侧立杆离墙面的静距离大于300mm时，应采取内设挑架板或其他隔离防护的安全措施（     ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_531"},{"id":532,"type":"judge","stem":"门式作业脚手架顶端防护栏杆宜高出女儿墙上端或檐口上端1.5m（     ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_532"},{"id":533,"type":"judge","stem":"当移动门式作业架架体的高宽比大于2时，应在移动就位后使用前应设抛撑（    ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_533"},{"id":534,"type":"judge","stem":"当移动门式作业架架体的高宽比大于3时，应在移动就位后使用前应设抛撑（    ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_534"},{"id":535,"type":"judge","stem":"悬挑脚手架型钢悬挑梁锚固位置设置在楼板上时，楼板的厚度不宜小于120mm，如果楼板厚度小于120mm应采取加固措施。","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_535"},{"id":536,"type":"judge","stem":"悬挑脚手架一次悬挑高度不宜超过24m。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_536"},{"id":537,"type":"judge","stem":"单排、双排脚手架立杆接长可采用对接或搭接。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_537"},{"id":538,"type":"judge","stem":"开口型脚手架的两端必须设置连墙件，连墙件的垂直间距不应大于建筑物的层高，并且不应大于4m。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_538"},{"id":539,"type":"judge","stem":"脚手架脚手板应铺设牢靠、严实，并应用安全网双层兜底。施工层以下每隔15m应用安全网封闭。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_539"},{"id":540,"type":"judge","stem":"搭设悬挑脚手架锚固型钢的主体结构混凝土强度等级不得低于C20。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_540"},{"id":541,"type":"judge","stem":"脚手架在使用期间严禁拆除主节点处的纵、横水平杆，纵、横扫地杆和连墙件。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_541"},{"id":542,"type":"judge","stem":"扣件式钢管脚手架的扣件在螺栓拧紧扭力矩达到65N▪m时，不得发生破坏。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_542"},{"id":543,"type":"judge","stem":"双排脚手架搭设高度不宜超过50m，高度超过50m的双排脚手架，应采取分段搭设等措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_543"},{"id":544,"type":"judge","stem":"脚手架立杆顶端栏杆宜高出女儿墙上端1m，宜高出檐口上端1.2m。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_544"},{"id":545,"type":"judge","stem":"高度在24m及以上的双排脚手架应在外侧全立面连续设置剪刀撑；高度在24m以下的双排脚手架可不设剪刀撑。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_545"},{"id":546,"type":"judge","stem":"满堂脚手架搭设高度不宜超过36m，施工层不得超过1层。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_546"},{"id":547,"type":"judge","stem":"满堂脚手架应在架体外侧四周及内部纵、横向每6m至8m由底至顶设置连续的竖向剪刀撑。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_547"},{"id":548,"type":"judge","stem":"根据《建筑施工脚手架安全技术统一规定》GB51210-2016相关规定，钢管直径在41-50之间的，外径允许偏差为±0.5mm。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_548"},{"id":549,"type":"judge","stem":"高处作业吊篮用的提升机、安全锁应有独立的标牌，并应标明产品型号、技术参数、出厂编号、出厂日期、标定周期、制造单位等。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_549"},{"id":550,"type":"judge","stem":"附着式升降脚手架附着支承结构应包括附墙支座、悬臂梁及斜拉杆。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_550"},{"id":551,"type":"judge","stem":"附着式升降脚手架附墙支座支承在建筑物上连接处混凝土的强度应按设计要求确定，但不得小于C10。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_551"},{"id":552,"type":"judge","stem":"物料平台不得与附着式升降脚手架各部位和各构件相连，其荷载应直接传递给建筑工程结构。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_552"},{"id":553,"type":"judge","stem":"脚手架外侧采用的密目式安全立网的网目不应低于2000目/10cm²，且应可靠固定在架体上。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_553"},{"id":554,"type":"judge","stem":"附着式升降脚手架限制荷载自控系统某一机位荷载超过设计值的30%时，应能使该升降设备自动停机。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_554"},{"id":555,"type":"judge","stem":"当附着式升降脚手架水平支承桁架两端高差达到15mm时，水平高差同步控制系统应能使该提升设备自动停机。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_555"},{"id":556,"type":"judge","stem":"附着式升降脚手架附着支承结构的安装应符合设计要求，不得少装和使用不合格螺栓及连接件。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_556"},{"id":557,"type":"judge","stem":"附着式升降脚手架的升降设备、控制系统、防坠落装置等应采取防雨、防砸、防尘等措施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_557"},{"id":558,"type":"judge","stem":"遇五级及以上大风和大雨、大雪、浓雾和雷电等恶劣天气时，不得进行附着式升降脚手架升降作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_558"},{"id":559,"type":"judge","stem":"拆除附着式升降脚手架时应有可靠的防止人员与物料坠落的措施，拆除的材料及设备不得抛扔。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_559"},{"id":560,"type":"judge","stem":"高处作业吊篮的荷载可分为永久荷载（即恒载）和可变荷载（即活载）两类。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_560"},{"id":561,"type":"judge","stem":"高处作业吊篮的悬挑梁应前低后高，前后水平高差不应大于横梁长度的2%。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_561"},{"id":562,"type":"judge","stem":"高处作业吊篮安装时应按照专项施工方案，并在专业人员的指导下实施。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_562"},{"id":563,"type":"judge","stem":"高处作业吊篮正常工作时，人员不得从窗口等处或其他孔洞处出入吊篮，但可从建筑物顶部出入。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_563"},{"id":564,"type":"judge","stem":"高处作业吊篮的钢丝绳最小直径为6mm，安全钢丝绳直径应不大于工作钢丝绳直径。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_564"},{"id":565,"type":"judge","stem":"高处作业吊篮的工作钢丝绳和安全钢丝绳应悬挂在同一个悬挂点上。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_565"},{"id":566,"type":"judge","stem":"脚手架底层步距不应大于2m。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_566"},{"id":567,"type":"judge","stem":"连墙件应靠近主节点设置，这是为了便于连墙件设置。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_567"},{"id":568,"type":"judge","stem":"GB51210-2016规定，脚手架构配件应具有良好的互换性，且可重复使用。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_568"},{"id":569,"type":"judge","stem":"有限空间作业应严格执行“先检测、再通风、后作业 ”的原则（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_569"},{"id":570,"type":"judge","stem":"受限或密闭空间作业前，应按照氧气、可燃性气体、有毒有害气体的顺序进行气体检测，当气体浓度超过安全允许值时，严禁作业。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_570"},{"id":571,"type":"judge","stem":"土方超挖时基坑侧壁安全性存在隐患，侧壁失稳风险增大。正确做法应按“先撑后挖 ”的原则及设计文件要求执行。  （   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_571"},{"id":572,"type":"judge","stem":"基坑工程变形监测数据超过报警值，或出现基坑、周边建(构)筑、管线失稳破坏征兆时，应立即停止施工作业，可以不撤离人员，待险情排除后方可恢复施工。(    )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_572"},{"id":573,"type":"judge","stem":"浇筑混凝土时应对架体基础沉降、架体变形进行监控，基础沉降、架体变形应在规定允许范围内。  (   )","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_573"},{"id":574,"type":"judge","stem":"塔式起重机的力矩限制器、重量限制器、变幅限位器、行走限位器、高度限位器等安全保护装置不得随意调整和拆除，可以用限位装置代替操纵机构。  （   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_574"},{"id":575,"type":"judge","stem":"悬挑式操作平台的搁置点、拉结点、支撑点应设置在稳定的主体结构上，且应与脚手架可靠连接。  （   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_575"},{"id":576,"type":"judge","stem":"有限空间作业未对施工人员进行专项安全教育培训属于一般事故隐患。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_576"},{"id":577,"type":"judge","stem":"基坑侧壁出现大量漏水、流土，属于重大事故隐患。(   )","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_577"},{"id":578,"type":"judge","stem":"采用抗滑柱，挡土墙共同支挡时，应先做挡土墙后做抗滑桩。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_578"},{"id":579,"type":"judge","stem":"吊篮应独立设置作业人员专用的挂设安全带的安全绳。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_579"},{"id":580,"type":"judge","stem":"瓦斯隧道瓦斯含量低于0.5%时，应每0.5-1h检测一次，瓦斯含量高于0.5%时，应每15min检测一次。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_580"},{"id":581,"type":"judge","stem":"隧道洞口与桥梁路基等同一点有多个单位同时施工或洞内不同专业交叉作业时，应分别制订现场安全措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_581"},{"id":582,"type":"judge","stem":"隧道作业地段照明电压不宜大于36V，成洞段和不作业地段宜采用220V，照明灯具宜采用冷光源。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_582"},{"id":583,"type":"judge","stem":"冬季施工隧道内采用煤炭炉取暖应制定安全措施。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_583"},{"id":584,"type":"judge","stem":"洞口工程应先开挖后支护、自上而下分层开挖、分层支护。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_584"},{"id":585,"type":"judge","stem":"隧道施工按设计文件规定的施工方案。制定施工方案，地质条件发生变化时，应及时进行设计变更。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_585"},{"id":586,"type":"judge","stem":"隧道内反坡排水方案应根据距离、坡度、水量和设备情况确定，抽水机排水能力应大于排水量的20%，并应有备用台数。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_586"},{"id":587,"type":"judge","stem":"边坡开挖中如遇地下水涌出，先排水，后开挖。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_587"},{"id":588,"type":"judge","stem":"锚环和锚塞使用前，应认真仔细检查及实验，经检验合格后，方可使用。（   ）","options":["A.正确","B.错误"],"answer":"A","hasImage":false,"image":null,"globalId":"tech_判断_588"},{"id":589,"type":"judge","stem":"消解石灰时，操作人员应站在下风侧。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_589"},{"id":590,"type":"judge","stem":"地质条件不同的两孔隧道，宜先开挖地质条件较好隧道，后开挖地质条件较差的隧道。（   ）","options":["A.正确","B.错误"],"answer":"B","hasImage":false,"image":null,"globalId":"tech_判断_590"}]};